// ASYNC

export const parseText = async <T = unknown,>(
		stub: string,
		text: string,
		hOptions: hash = {}
		): AutoPromise<T> => {

	type opt = {
		trace: boolean
		abortOnError: boolean
		}
	const {trace, abortOnError} = getOptions<opt>(hOptions, {
		trace: false,
		abortOnError: true
		})

	debugger
	let parseMatcher
	try {
		// --- Make sure parser is compiled and up to date
		const heraFileName = `${stub}.parse.hera`
		const heraPath = findFile(heraFileName)
		assert(defined(heraPath), `No such file: ${heraFileName}`)
		const hResult = await procOneFile(heraPath, doCompileHera)
		assert(hResult.success, `parse of ${heraPath} failed`)

		const tsFileName = `${stub}.parse.ts`
		DBG(`tsFileName = ${tsFileName}`)
		const path = findFile(tsFileName)
		assert(defined(path), "No such file: ${tsFileName}")
		assert(isFile(path), `Not a file: ${path}`)

		const fileURL = toFileUrl(path).href
		const {pm, beginParse, parse} = await import(fileURL)
		parseMatcher = pm
		assert(defined(parse), "Parser not found")
		assert(isFunction(parse), "Parser not a function")

		const newText = beginParse(text)
		if (isString(newText)) {
			text = newText
		}

		pm.reset(text)

		// --- I don't know why parse() sometimes returns a function
		//     that must be called to get the actual return value
		let result = parse(text)
		if (isFunction(result)) {
			result = result()
		}

		if (trace) {
			pm.dumpParseInfo()
		}

		// --- Return a deep copy of the result
		return deepCopy(result)
	}

	catch (err) {
		if (curLogLevel() !== 'silent') {
			ERR(err)
			ERR(`Parser: '${stub}'`, 'PARSE ERROR')
			LOG(`Parsing: ${esc(text)}`)
			parseMatcher.dumpParseInfo()
		}
		throw err
	}
}

// ---------------------------------------------------------------------------
// ASYNC

export const parseFile = async <T = unknown,>(
		stub: string,
		path: string,
		hOptions: hash = {}
		): AutoPromise<T> => {

	const [hMetaData, contents] = await openAndReadTextFile(path)
	return await parseText<T>(stub, contents, {hMetaData})
}

